using Microsoft.CodeAnalysis;
using System.Text;

namespace SharpPack.Generator;

internal readonly record struct GeneratedSource(string HintName, string Text);

internal sealed partial class CSharpEmitter(SerializationPlan plan, string? constructionTypeName = null)
{
    static void AppendPreamble(StringBuilder sb)
        => sb.AppendLine(@"
// <auto-generated/>
#nullable enable
#pragma warning disable CS0108 // hides inherited member
#pragma warning disable CS0162 // Unreachable code
#pragma warning disable CS0164 // This label has not been referenced
#pragma warning disable CS0219 // Variable assigned but never used
#pragma warning disable CS0618 // Type or member is obsolete
#pragma warning disable CS8600 // Converting null literal or possible null value to non-nullable type.
#pragma warning disable CS8601 // Possible null reference assignment
#pragma warning disable CS8602
#pragma warning disable CS8604 // Possible null reference argument for parameter
#pragma warning disable CS8619
#pragma warning disable CS8620
#pragma warning disable CS8631 // The type cannot be used as type parameter in the generic type or method
#pragma warning disable CS8765 // Nullability of type of parameter
#pragma warning disable CS9074 // The 'scoped' modifier of parameter doesn't match overridden or implemented member
#pragma warning disable CA1050 // Declare types in namespaces.

using System;
using SharpPack;
");

    internal GeneratedSource EmitModel(bool fileScopedNamespace)
    {
        var sb = new StringBuilder();
        AppendPreamble(sb);

        // The formatter must join its declaration; registration remains in
        // the target namespace so existing callers keep the same extension.
        var separateRegistration = Shape.Union is { ExternalFormatter: { } formatter } union &&
            formatter.Namespace != Shape.Namespace ? union : null;
        var ns = separateRegistration?.ExternalFormatter?.Namespace ?? Shape.Namespace;
        var useFileScopedNamespace = fileScopedNamespace && separateRegistration is null;
        if (ns.Length != 0)
        {
            if (useFileScopedNamespace)
            {
                sb.AppendLine($"namespace {ns};");
            }
            else
            {
                sb.AppendLine($"namespace {ns} {{");
            }
        }
        sb.AppendLine();

        if (HasSerializationInfo(Shape))
            BuildDebugInfo(sb, Shape, xmlDocument: true);

        EmitTemplate(sb, includeExternalRegistration: separateRegistration is null);

        if (ns.Length != 0 && !useFileScopedNamespace)
        {
            sb.AppendLine("}");
        }

        if (separateRegistration is { ExternalFormatter: { } declaredFormatter })
        {
            var targetNamespace = Shape.Namespace;
            if (targetNamespace.Length != 0)
                sb.AppendLine($"namespace {targetNamespace} {{");
            sb.AppendLine(EmitUnionContextRegistration(separateRegistration.TypeName, declaredFormatter, declaredFormatter.QualifiedName));
            if (targetNamespace.Length != 0)
                sb.AppendLine("}");
        }

        return new($"{ModelFileStem(Shape)}.SharpPackFormatter.g.cs", sb.ToString());
    }

    internal static bool HasSerializationInfo(TypeShape shape)
        => shape.GenerateType is GenerateType.Object or GenerateType.VersionTolerant or GenerateType.CircularReference;

    internal static string ModelFileStem(TypeShape shape)
        => shape.DeclarationName.Replace("@", "").Replace("global::", "").Replace("<", "_").Replace(">", "_");

    internal static string EmitSerializationInfo(TypeShape shape)
    {
        var writer = new StringBuilder();
        BuildDebugInfo(writer, shape, xmlDocument: false);
        return writer.ToString();
    }

    static void BuildDebugInfo(StringBuilder sb, TypeShape type, bool xmlDocument)
    {
        string WithEscape(string qualifiedName)
        {
            var str = qualifiedName.Replace("global::", "");
            if (xmlDocument)
            {
                return str.Replace("<", "&lt;").Replace(">", "&gt;");
            }
            else
            {
                return str;
            }
        }

        if (!xmlDocument)
        {
            if (type.IsUnmanaged)
            {
                sb.Append("GenerateType unmanaged ");
            }
            else
            {
                sb.Append("GenerateType " + type.GenerateType.ToString() + " ");
            }
            sb.AppendLine(WithEscape(type.TargetName));
            sb.AppendLine("---");
        }
        else
        {
            sb.AppendLine("/// <remarks>");
            if (type.IsUnmanaged)
            {
                sb.AppendLine("/// SharpPack GenerateType: unmanaged<br/>");
            }
            else
            {
                sb.AppendLine("/// SharpPack GenerateType: " + type.GenerateType.ToString() + "<br/>");
            }
            sb.AppendLine("/// <code>");
        }

        foreach (var item in type.Members)
        {
            if (xmlDocument)
            {
                sb.Append("/// <b>");
            }

            sb.Append(WithEscape(item.TypeName));
            if (xmlDocument)
            {
                sb.Append("</b>");
            }

            sb.Append(" ");
            sb.Append(item.Name);

            if (xmlDocument)
            {
                sb.AppendLine("<br/>");
            }
            else
            {
                sb.AppendLine();
            }
        }
        if (xmlDocument)
        {
            sb.AppendLine("/// </code>");
            sb.AppendLine("/// </remarks>");
        }
    }
    TypeShape Shape => plan.Shape;
    string TypeName => constructionTypeName ?? Shape.ShortName;
    bool IsValueType => Shape.IsValueType;
    bool UsesEmptyConstructor => Shape.ConstructorParameters.Length == 0;

    MemberShape[] WireMembers() => plan.WireSlots.Select(slot => slot.DeclaredMemberIndex is int index
        ? Shape.Members[index] : MemberShape.Blank(slot.Position)).ToArray();

    internal void EmitTemplate(StringBuilder writer, bool includeExternalRegistration = true)
    {
        var shape = plan.Shape;
        foreach (var container in shape.ContainingTypes)
        {
            writer.AppendLine(EmitPartialTypeDeclaration(container));
            writer.AppendLine("{");
        }

        if (shape.Union is { } union)
        {
            writer.AppendLine(union.IsNative ? EmitNativeUnionTemplate(union)
                : union.ExternalFormatter is { } formatter
                    ? EmitUnionFormatterTemplate(union, formatter, includeExternalRegistration)
                    : EmitUnionTemplate(union));
        }
        else if (shape.Collection is { } collection)
        {
            writer.AppendLine(EmitGenericCollectionTemplate(collection, plan.Names.SelfFactoryRoot));
        }
        else
        {
            EmitObjectTemplate(writer);
        }

        for (var i = 0; i < shape.ContainingTypes.Length; i++)
            writer.AppendLine("}");
    }

    void EmitObjectTemplate(StringBuilder writer)
    {
        var shape = plan.Shape;
        var serializeBody = "";
        var deserializeBody = "";
        var formatterOverrideMethods = "";
        var circularReadConstructor = "";
        var contextFormatterTypeName = plan.Names.ContextFormatterType;
        if (shape.IsUnmanaged)
        {
            serializeBody = $$"""
        writer.WriteUnmanaged(value);
""";
            deserializeBody = $$"""
        reader.ReadUnmanaged(out value);
""";
        }
        else
        {
            var wireMembers = WireMembers();
            serializeBody = EmitSerializeBody(wireMembers);
            deserializeBody = EmitDeserializeBody(wireMembers, honorFormatterOverrides: false);
            formatterOverrideMethods = EmitFormatterOverrideMethods(wireMembers);
            if (shape.CircularRead is { } circularRead)
                circularReadConstructor = EmitCircularReadConstructor(wireMembers, circularRead);
        }

        var classOrStructOrRecord = (shape.IsRecord, IsValueType) switch
        {
            (true, true) => "record struct",
            (true, false) => "record",
            (false, true) => "struct",
            (false, false) => "class",
        };

        var nullable = IsValueType ? "" : "?";

        var staticSharpPackableMethod =
            $"static void global::SharpPack.ISharpPackable<{TypeName}>.";
        const string scopedRef = "scoped ref";
        var fixedSizeInterface = "";
        var fixedSizeMethod = "";
        var exactSizeInterface = "";
        var exactSizeMethod = "";
        if (plan.RootFastPath == RootFastPath.FixedSize)
        {
            var sizeOf = string.Join(
                " + ",
                shape.Members.Select(member =>
                    $"global::System.Runtime.CompilerServices.Unsafe.SizeOf<{member.TypeName}>()"));
            var headerPlus = shape.Members.Length == 0 ? "1" : "1 + ";
            fixedSizeInterface = ", global::SharpPack.IFixedSizeSharpPackable";
            fixedSizeMethod = $$"""

    [global::SharpPack.CompilerServices.Preserve]
    static int global::SharpPack.IFixedSizeSharpPackable.Size => {{headerPlus}}{{sizeOf}};

""";
        }

        else if (plan.RootFastPath == RootFastPath.ExactSize)
        {
            exactSizeInterface =
                $", global::SharpPack.ISharpPackExactSizeSerializable<{TypeName}>";
            exactSizeMethod = EmitExactSizeSerializeMethod();
        }
        var writerParameter = shape.WriterTypeParameter;

        var contextFactoryInterface =
            $", global::SharpPack.ISharpPackFormatterFactory<{TypeName}>" +
            $", global::SharpPack.ISharpPackContextFormatterFactory<{TypeName}>";
        var genericWriterConstraint = $"where {writerParameter} : global::System.Buffers.IBufferWriter<byte>";
        var serializeMethod = plan.TracksReferences ? $"static void {plan.Names.WriteCircular}" : staticSharpPackableMethod + "Serialize";
        var deserializeMethod = plan.TracksReferences ? $"static void {plan.Names.ReadCircular}" : staticSharpPackableMethod + "Deserialize";
        var circularFormatter = plan.TracksReferences ? EmitCircularFormatter(TypeName + nullable, writerParameter) : "";
        var defaultFormatter = plan.TracksReferences
            ? $"new {plan.Names.CircularFormatter}()"
            : $"new global::SharpPack.Formatters.SharpPackableFormatter<{TypeName}>()";
        var contextDependencyCondition = string.Join(" || ", plan.ContextDependencies.FactoryLookupTypes
            .Select(static type => $"context.HasFormatterOverrideDependency<{type}>()"));
        var contextFormatterSelection =
            contextDependencyCondition.Length == 0
                ? $"return {defaultFormatter};"
                : $$"""
        if ({{contextDependencyCondition}})
        {
            return new {{contextFormatterTypeName}}();
        }
        return {{defaultFormatter}};
""";
        var selfFactoryRoot = plan.Names.SelfFactoryRoot;
        var selfFactoryRootRead = EmitFactoryRootRead(selfFactoryRoot);
        var aotFormatterRoots = EmitAotFormatterRoots(plan.AotRoots, "        ");
        var aotRootMethodName = plan.Names.EnsureAotRoots;
        var aotRootCall = aotFormatterRoots.Length == 0
            ? ""
            : $"        {aotRootMethodName}();";
        var aotRootMethod = aotFormatterRoots.Length == 0
            ? ""
            : $$"""

    [global::SharpPack.CompilerServices.Preserve]
    static void {{aotRootMethodName}}()
    {
{{aotFormatterRoots}}
    }
""";
        var contextFactoryMethod = $$"""

    [global::SharpPack.CompilerServices.Preserve]
    static global::SharpPack.SharpPackFormatter<{{TypeName}}> global::SharpPack.ISharpPackFormatterFactory<{{TypeName}}>.CreateFormatter()
    {
{{selfFactoryRootRead}}
{{aotRootCall}}
        return {{defaultFormatter}};
    }

    [global::SharpPack.CompilerServices.Preserve]
    static global::SharpPack.SharpPackFormatter<{{TypeName}}> global::SharpPack.ISharpPackContextFormatterFactory<{{TypeName}}>.CreateFormatter(
        global::SharpPack.SharpPackSerializerContext context)
    {
{{selfFactoryRootRead}}
{{aotRootCall}}
        {{contextFormatterSelection}}
    }
{{aotRootMethod}}
""";

        writer.AppendLine($$"""
partial {{classOrStructOrRecord}} {{TypeName}} : global::SharpPack.ISharpPackable<{{TypeName}}>{{fixedSizeInterface}}{{exactSizeInterface}}{{contextFactoryInterface}}
{
{{(shape.IsUnmanaged ? "" : EmitCustomFormatters(shape.Members))}}
    static partial void StaticConstructor();

{{EmitSelfFactoryRoots(selfFactoryRoot, includeContextFactory: true)}}
{{fixedSizeMethod}}
{{exactSizeMethod}}
{{contextFactoryMethod}}
{{formatterOverrideMethods}}{{circularReadConstructor}}{{circularFormatter}}

    [global::SharpPack.CompilerServices.Preserve]
    {{serializeMethod}}<{{writerParameter}}>(ref global::SharpPack.SharpPackWriter<{{writerParameter}}> writer, {{scopedRef}} {{TypeName}}{{nullable}} value){{(plan.TracksReferences ? "\n        " + genericWriterConstraint : "")}}
    {
{{EmitCallbacks(shape, CallbackPhase.Serializing)}}
{{serializeBody}}
    END:
{{EmitCallbacks(shape, CallbackPhase.Serialized)}}
        return;
    }

    [global::SharpPack.CompilerServices.Preserve]
    {{deserializeMethod}}(ref global::SharpPack.SharpPackReader reader, {{scopedRef}} {{TypeName}}{{nullable}} value)
    {
{{EmitCallbacks(shape, CallbackPhase.Deserializing)}}
{{deserializeBody}}
    END:
{{EmitCallbacks(shape, CallbackPhase.Deserialized)}}
        return;
    }

}
""");
    }

    // Bind circular writers to their model at compile time. NativeAOT's generic
    // formatter adapter can miss the virtual writer instantiation for a cycle.
    string EmitCircularFormatter(string valueType, string writerParameter) => $$"""

    [global::SharpPack.CompilerServices.Preserve]
    static void global::SharpPack.ISharpPackable<{{TypeName}}>.Serialize<{{writerParameter}}>(
        ref global::SharpPack.SharpPackWriter<{{writerParameter}}> writer, scoped ref {{valueType}} value)
        => {{plan.Names.WriteCircular}}(ref writer, ref value);

    [global::SharpPack.CompilerServices.Preserve]
    static void global::SharpPack.ISharpPackable<{{TypeName}}>.Deserialize(ref global::SharpPack.SharpPackReader reader, scoped ref {{valueType}} value)
        => {{plan.Names.ReadCircular}}(ref reader, ref value);

    [global::SharpPack.CompilerServices.Preserve]
    sealed class {{plan.Names.CircularFormatter}} : global::SharpPack.SharpPackFormatter<{{TypeName}}>
    {
        public override void Serialize<{{writerParameter}}>(ref global::SharpPack.SharpPackWriter<{{writerParameter}}> writer, scoped ref {{valueType}} value)
            => {{plan.Names.WriteCircular}}(ref writer, ref value);

        public override void Deserialize(ref global::SharpPack.SharpPackReader reader, scoped ref {{valueType}} value)
            => {{plan.Names.ReadCircular}}(ref reader, ref value);
    }
""";

    string EmitDeserializeBody(MemberShape[] members, bool honorFormatterOverrides)
    {
        var count = members.Length;

        var isVersionTolerant = plan.IsVersioned;
        var readBeginBody = "";
        var readEndBody = "";
        var commentOutInvalidBody = "";
        var circularReferenceBody = "";
        var circularReferenceBody2 = "";

        if (isVersionTolerant)
        {
            readBeginBody = """
        global::System.Span<int> deltas = stackalloc int[count];
        long totalDelta = 0;
        for (int i = 0; i < count; i++)
        {
            deltas[i] = reader.ReadVarIntInt32();
            if (deltas[i] < 0)
            {
                global::SharpPack.SharpPackSerializationException.ThrowInvalidLength(deltas[i]);
            }
            totalDelta += deltas[i];
        }
        if (totalDelta > reader.Remaining)
        {
            global::SharpPack.SharpPackSerializationException.ThrowInvalidAdvance();
        }
""";

            readEndBody = """
        if (count == readCount) goto END;

        for (int i = readCount; i < count; i++)
        {
            reader.Advance(deltas[i]);
        }
""";

            commentOutInvalidBody = "// ";
        }
        if (plan.TracksReferences)
        {
            circularReferenceBody = $$"""
        uint id;
        if (count == global::SharpPack.SharpPackCode.ReferenceId)
        {
            id = reader.ReadVarIntUInt32();
            value = ({{TypeName}})reader.OptionalState.GetObjectReference(id);
            goto END;
        }
""";

            circularReferenceBody2 = $$"""
        id = reader.ReadVarIntUInt32();
        if (value == null)
        {
            value = new {{TypeName}}();
        }
        reader.OptionalState.AddObjectReference(id, value);
""";
        }

        var readHeader = $$"""
        if (!reader.TryReadObjectHeader(out var count))
        {
            value = default!;
            goto END;
        }
{{circularReferenceBody}}
{{readBeginBody}}
""";
        if (Shape.CircularRead is { } circularRead)
            return readHeader + Environment.NewLine + EmitCircularReadBody(members, circularRead, honorFormatterOverrides);

        return $$"""
{{readHeader}}
{{circularReferenceBody2}}
{{members.Where(x => x.Kind != MemberKind.Blank).Select(x => $"        {x.TypeName} __{x.Name};").NewLine()}}

        {{(!isVersionTolerant ? "" : "var readCount = " + count + ";")}}
        if (count == {{count}})
        {
            {{(IsValueType ? "" : "if (value == null)")}}
            {
{{EmitDeserializeMembersCore(
    members,
    plan.ScalarBatches,
    "                ",
    isVersionTolerant,
    honorFormatterOverrides)}}

                goto NEW;
            }
{{(IsValueType ? "#if false" : "            else")}}
            {
{{members.Where(x => x.Kind != MemberKind.Blank).Select(x => $"                __{x.Name} = value.@{x.Name};").NewLine()}}

{{EmitReadRefDeserializeMembers(
    members,
    "                ",
    includeCountJumps: false,
    honorFormatterOverrides)}}

                goto SET;
            }
{{(IsValueType ? "#endif" : "")}}
        }
        {{commentOutInvalidBody}}else if (count > {{count}})
        {{commentOutInvalidBody}}{
            {{commentOutInvalidBody}}global::SharpPack.SharpPackSerializationException.ThrowInvalidPropertyCount(typeof({{TypeName}}), {{count}}, count);
            {{commentOutInvalidBody}}goto READ_END;
        {{commentOutInvalidBody}}}
        else
        {
            {{(IsValueType ? "" : "if (value == null)")}}
            {
{{members.Where(x => x.Kind != MemberKind.Blank).Select(x => $"               __{x.Name} = default!;").NewLine()}}
            }
{{(IsValueType ? "#if false" : "            else")}}
            {
{{members.Where(x => x.Kind != MemberKind.Blank).Select(x => $"               __{x.Name} = value.@{x.Name};").NewLine()}}
            }
{{(IsValueType ? "#endif" : "")}}

            if (count == 0) goto SKIP_READ;
{{EmitReadRefDeserializeMembers(
    members,
    "            ",
    includeCountJumps: true,
    honorFormatterOverrides)}}

    SKIP_READ:
            {{(IsValueType ? "" : "if (value == null)")}}
            {
                goto NEW;
            }
{{(IsValueType ? "#if false" : "            else")}}
            {
                goto SET;
            }
{{(IsValueType ? "#endif" : "")}}
        }

    SET:
        {{(!UsesEmptyConstructor ? "goto NEW;" : "")}}
{{members.Where(x => x.IsAssignable).Select(x => $"        {(UsesEmptyConstructor ? "" : "// ")}value.@{x.Name} = __{x.Name};").NewLine()}}
        goto READ_END;

    NEW:
        value = {{EmitConstructor(members)}}
        {
{{EmitDeserializeConstruction(members, "            ")}}
        };
{{EmitDeserializeConstructionWithBranching(members, "        ")}}
    READ_END:
{{readEndBody}}
""";
    }

    static string EmitCallbacks(TypeShape shape, CallbackPhase phase, string indent = "        ")
        => shape.IsUnmanaged ? "" : shape.Callbacks.Where(callback => callback.Phase == phase)
            .Select(callback => indent + EmitCallbackInvocation(
                callback.Name, callback.IsStatic, callback.IsValueType, callback.PassArguments
                    ? (phase is CallbackPhase.Serializing or CallbackPhase.Serialized
                        ? "ref writer, ref value" : "ref reader, ref value")
                    : "")).NewLine();

    internal static string EmitCallbackInvocation(string name, bool isStatic, bool isValueType, string arguments)
        => $"{(isStatic ? "" : isValueType ? "value." : "value?.")}{name}({arguments});";

    static string EmitCustomFormatters(EquatableArray<MemberShape> members)
    {
        var sb = new StringBuilder();
        foreach (var item in members)
        {
            if (item.CustomFormatter is not { } attribute) continue;
            var arguments = string.Join(
                ", ",
                attribute.Arguments.Select(EmitTypedConstant));
            var initializers = attribute.Initializers
                .Select(static pair => $"@{pair.Name} = {EmitTypedConstant(pair.Value)}")
                .ToArray();
            var initializer = initializers.Length == 0
                ? ""
                : $" {{ {string.Join(", ", initializers)} }}";

            sb.AppendLine(
                $"    static readonly {attribute.FormatterType} __{item.Name}Formatter = " +
                $"new {attribute.AttributeType}({arguments})" +
                $"{initializer}.GetFormatter();");
        }
        return sb.ToString();
    }

    static string EmitTypedConstant(AttributeValueShape constant)
    {
        if (constant.IsNull)
        {
            return "null";
        }

        return constant.Kind switch
        {
            TypedConstantKind.Primitive =>
                Microsoft.CodeAnalysis.CSharp.SymbolDisplay.FormatPrimitive(
                    constant.Scalar!,
                    quoteStrings: true,
                    useHexadecimalNumbers: false),
            TypedConstantKind.Enum =>
                $"({constant.TypeName})" +
                Microsoft.CodeAnalysis.CSharp.SymbolDisplay.FormatPrimitive(
                    constant.Scalar!,
                    quoteStrings: false,
                    useHexadecimalNumbers: false),
            TypedConstantKind.Type =>
                $"typeof({constant.TypeName})",
            TypedConstantKind.Array =>
                $"new {constant.TypeName}[]" +
                $" {{ {string.Join(", ", constant.Elements.Select(EmitTypedConstant))} }}",
            _ => throw new InvalidOperationException(
                $"Unsupported custom formatter attribute argument: {constant.Kind}."),
        };
    }

    internal static string EmitFactoryRootRead(string? name)
        => name is null ? "" : $"        var {name} = {name}Value;";

    string EmitSelfFactoryRoots(string? name, bool includeContextFactory)
        => name is not null
            ? EmitFactoryRootField(name, TypeName, includeContextFactory)
            : $$"""
    static {{Shape.SimpleName}}()
    {
        StaticConstructor();
{{EmitFactoryPreservation("        ", TypeName, includeContextFactory)}}
    }
""";

    internal static string EmitFactoryRootField(string name, string typeName, bool includeContextFactory)
        => $$"""
    private static readonly bool {{name}}Value = {{name}}();
    private static bool {{name}}()
    {
{{EmitFactoryPreservation("        ", typeName, includeContextFactory)}}
        return true;
    }
""";

    static string EmitFactoryPreservation(string indent, string type, bool includeContextFactory)
        => $"{indent}global::SharpPack.SharpPackSerializer.PreserveFormatterFactory<{type}>();" +
            (includeContextFactory
                ? $"\n{indent}global::SharpPack.SharpPackSerializer.PreserveContextFormatterFactory<{type}>();"
                : "");

    // The deserialization API retains model static constructors. Those roots
    // and the first factory creation retain typed dependencies without relying
    // on Roslyn's private explicit-interface metadata spelling.
    static string EmitAotFormatterRoots(AotRootSet roots, string indent)
    {
        var sb = new StringBuilder();
        // Factory methods are needed by trimmed JIT as well as NativeAOT.
        foreach (var entry in roots.Factories)
        {
            sb.AppendLine(EmitFactoryPreservation(indent, entry.TypeName, entry.HasContextFactory));
        }
        if (roots.ClosedFormatters.Length != 0)
        {
            sb.AppendLine(
                $"{indent}if (!global::System.Runtime.CompilerServices.RuntimeFeature.IsDynamicCodeSupported)");
            sb.AppendLine($"{indent}{{");
            foreach (var formatterType in roots.ClosedFormatters)
            {
                sb.AppendLine(
                    $"{indent}    global::System.GC.KeepAlive(new {formatterType}());");
            }
            sb.AppendLine($"{indent}}}");
        }
        return sb.ToString().TrimEnd('\r', '\n');
    }

    string EmitSerializeBody(MemberShape[] members)
        => plan.ObjectWriteStrategy switch
        {
            ObjectWriteStrategy.VersionedInlineLengths => EmitVersionedSerializeBodyWithInlineLengths(members, plan.ScalarBatches),
            ObjectWriteStrategy.VersionedBufferedLengths => EmitVersionedSerializeBody(members, honorFormatterOverrides: false),
            _ => EmitObjectSerializeBody(members, plan.ScalarBatches, honorFormatterOverrides: false),
        };

    string EmitExactSizeSerializeMethod()
    {
        var members = Shape.Members;
        var captureMembers = members
            .Select((member, index) => member.Kind == MemberKind.String
                ? $"""
        var __value{index} = this.@{member.Name};
        var __utf8Length{index} = __value{index} is null || __value{index}.Length == 0
            ? 0
            : global::System.Text.Encoding.UTF8.GetByteCount(__value{index});
"""
                : $"        var __value{index} = this.@{member.Name};")
            .NewLine();
        var sizeTerms = members
            .Select((member, index) => member.Kind switch
            {
                MemberKind.Unmanaged or
                MemberKind.Enum or
                MemberKind.UnmanagedNullable =>
                    $"global::System.Runtime.CompilerServices.Unsafe.SizeOf<{member.TypeName}>()",
                MemberKind.String =>
                    $"(__value{index} is null || __value{index}.Length == 0 ? 4L : (long)__utf8Length{index} + 8)",
                MemberKind.UnmanagedArray =>
                    $"(__value{index} is null || __value{index}.Length == 0 ? 4L : (long)__value{index}.Length * global::System.Runtime.CompilerServices.Unsafe.SizeOf<{member.ElementTypeName}>() + 4)",
                _ => throw new InvalidOperationException(),
            });
        var writeMembers = members
            .Select((member, index) => member.Kind switch
            {
                MemberKind.Unmanaged or MemberKind.Enum =>
                    $"        writer.WriteUnmanaged(__value{index});",
                MemberKind.UnmanagedNullable =>
                    $"        writer.DangerousWriteUnmanaged(__value{index});",
                MemberKind.String =>
                    $"        writer.WriteUtf8Exact(__value{index}, __utf8Length{index});",
                MemberKind.UnmanagedArray =>
                    $"        writer.WriteUnmanagedArray(__value{index});",
                _ => throw new InvalidOperationException(),
            })
            .NewLine();
        var sizeExpression = string.Join(
            " + " + Environment.NewLine + "            ",
            sizeTerms);

        return $$"""

    [global::SharpPack.CompilerServices.Preserve]
    byte[] global::SharpPack.ISharpPackExactSizeSerializable<{{TypeName}}>.SerializeExact()
    {
{{captureMembers}}
        var size = 1L +
            {{sizeExpression}};
        if ((ulong)size > (ulong)global::System.Array.MaxLength)
        {
            global::SharpPack.SharpPackSerializationException.ThrowSizeOverflow();
        }
        var buffer = global::System.GC.AllocateUninitializedArray<byte>((int)size);
        var bufferWriter =
            new global::SharpPack.Internal.SharpPackExactArrayBufferWriter(buffer);
        var writer = global::SharpPack.SharpPackSerializer.CreateExactWriter(
            ref bufferWriter);
        writer.WriteObjectHeader({{members.Length}});
{{writeMembers}}
        writer.Flush();
        return bufferWriter.GetFilledBuffer();
    }
""";
    }

    string EmitFormatterOverrideMethods(MemberShape[] members)
    {
        var shape = plan.Shape;
        if (!plan.ContextDependencies.HasOverridableWireMembers)
        {
            return "";
        }

        var overrideSerializeBody =
            plan.IsVersioned
                ? EmitVersionedSerializeBody(
                    members, honorFormatterOverrides: true)
                : EmitObjectSerializeBody(
                    members, plan.ScalarBatches, honorFormatterOverrides: true);
        var overrideDeserializeBody = EmitDeserializeBody(members, honorFormatterOverrides: true);
        var nullable = IsValueType ? "" : "?";
        var serializeHelperName = plan.Names.WriteWithOverrides;
        var deserializeHelperName = plan.Names.ReadWithOverrides;
        var writerParameter = Shape.WriterTypeParameter;

        return $$"""

    [global::System.Runtime.CompilerServices.MethodImpl(
        global::System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
    static void {{serializeHelperName}}<{{writerParameter}}>(
        ref global::SharpPack.SharpPackWriter<{{writerParameter}}> writer,
        scoped ref {{TypeName}}{{nullable}} value)
        where {{writerParameter}} : global::System.Buffers.IBufferWriter<byte>
    {
{{EmitCallbacks(shape, CallbackPhase.Serializing)}}
{{overrideSerializeBody}}
    END:
{{EmitCallbacks(shape, CallbackPhase.Serialized)}}
        return;
    }

    [global::System.Runtime.CompilerServices.MethodImpl(
        global::System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]
    static void {{deserializeHelperName}}(
        ref global::SharpPack.SharpPackReader reader,
        scoped ref {{TypeName}}{{nullable}} value)
    {
{{EmitCallbacks(shape, CallbackPhase.Deserializing)}}
{{overrideDeserializeBody}}
    END:
{{EmitCallbacks(shape, CallbackPhase.Deserialized)}}
        return;
    }

    [global::SharpPack.CompilerServices.Preserve]
    sealed class {{plan.Names.ContextFormatterType}}
        : global::SharpPack.SharpPackFormatter<{{TypeName}}>,
          global::SharpPack.ISharpPackContextOverrideFormatter
    {
        public override void Serialize<{{writerParameter}}>(
            ref global::SharpPack.SharpPackWriter<{{writerParameter}}> writer,
            scoped ref {{TypeName}}{{nullable}} value)
            => {{serializeHelperName}}(ref writer, ref value);

        public override void Deserialize(
            ref global::SharpPack.SharpPackReader reader,
            scoped ref {{TypeName}}{{nullable}} value)
            => {{deserializeHelperName}}(ref reader, ref value);
    }
""";
    }

    string EmitObjectSerializeBody(MemberShape[] members, EquatableArray<ScalarBatch> batches, bool honorFormatterOverrides)
    {
        return $$"""
{{(!IsValueType ? $$"""
        if (value == null)
        {
            writer.WriteNullObjectHeader();
            goto END;
        }
""" : "")}}

{{EmitSerializeMembersCore(
    members,
    batches,
    "        ",
    toTempWriter: false,
    writeObjectHeader: true,
    honorFormatterOverrides)}}
""";
    }

    string EmitVersionedSerializeBody(MemberShape[] members, bool honorFormatterOverrides)
    {
        const string newTempWriter =
            "new global::SharpPack.SharpPackWriter<global::SharpPack.Internal.ReusableLinkedArrayBufferWriter>(ref tempBuffer, writer.OptionalState)";

        var checkCircularReference = "";
        if (plan.TracksReferences)
        {
            checkCircularReference = """
        var (existsReference, id) = writer.OptionalState.GetOrAddReference(value);
        if (existsReference)
        {
            writer.WriteObjectReferenceId(id);
            goto END;
        }
""";
        }

        return $$"""
{{(!IsValueType ? $$"""
        if (value == null)
        {
            writer.WriteNullObjectHeader();
            goto END;
        }
""" : "")}}
{{checkCircularReference}}
        var tempBuffer = global::SharpPack.Internal.ReusableLinkedArrayBufferWriterPool.Rent(
            out var tempBufferLeaseId);
        try
        {
            global::System.Span<int> offsets = stackalloc int[{{members.Length}}];
            var tempWriter = {{newTempWriter}};

{{EmitSerializeMembersCore(
    members,
    default,
    "            ",
    toTempWriter: true,
    writeObjectHeader: false,
    honorFormatterOverrides)}}

            tempWriter.Flush();

            writer.WriteObjectHeader({{members.Length}});
            for (int i = 0; i < {{members.Length}}; i++)
            {
                int delta;
                if (i == 0)
                {
                    delta = offsets[i];
                }
                else
                {
                    delta = offsets[i] - offsets[i - 1];
                }
                writer.WriteVarInt(delta);
            }
            {{(plan.TracksReferences ? "writer.WriteVarInt(id);" : "")}}
            tempBuffer.WriteToAndReset(ref writer);
        }
        finally
        {
            global::SharpPack.Internal.ReusableLinkedArrayBufferWriterPool.Return(
                tempBuffer,
                tempBufferLeaseId);
        }
""";
    }

    string EmitVersionedSerializeBodyWithInlineLengths(MemberShape[] members, EquatableArray<ScalarBatch> batches)
    {
        static string EmitLengthHeader(MemberShape[] members)
        {
            var sb = new StringBuilder();
            foreach (var item in members)
            {
                sb.AppendLine("        " + item.EmitVarIntLength());
            }
            return sb.ToString();
        }

        var checkCircularReference = "";
        if (plan.TracksReferences)
        {
            checkCircularReference = """
        var (existsReference, id) = writer.OptionalState.GetOrAddReference(value);
        if (existsReference)
        {
            writer.WriteObjectReferenceId(id);
            goto END;
        }
""";
        }

        return $$"""
{{(!IsValueType ? $$"""
        if (value == null)
        {
            writer.WriteNullObjectHeader();
            goto END;
        }
""" : "")}}
{{checkCircularReference}}
        writer.WriteObjectHeader({{members.Length}});
{{EmitLengthHeader(members)}}
        {{(plan.TracksReferences ? "writer.WriteVarInt(id);" : "")}}
{{EmitSerializeMembersCore(members, batches, "        ", toTempWriter: false, writeObjectHeader: false)}}
""";
    }

    internal static string EmitSerializeMembersCore(
        MemberShape[] members,
        EquatableArray<ScalarBatch> batches,
        string indent,
        bool toTempWriter,
        bool writeObjectHeader,
        bool honorFormatterOverrides = false)
    {
        if (members.Length == 0 && writeObjectHeader)
        {
            return $"{indent}writer.WriteObjectHeader(0);";
        }

        var writer = toTempWriter ? "tempWriter" : "writer";

        var sb = new StringBuilder();
        for (int i = 0; i < members.Length; i++)
        {
            var batch = toTempWriter || honorFormatterOverrides ? default : batches[i];
            if (batch.Count == 0)
            {
                sb.Append(indent);
                if (i == 0 && writeObjectHeader)
                {
                    sb.AppendLine($"{writer}.WriteObjectHeader({members.Length});");
                    sb.Append(indent);
                }

                sb.Append(members[i].EmitSerialize(
                    writer,
                    honorFormatterOverrides));
                if (toTempWriter)
                {
                    sb.AppendLine($" offsets[{i}] = tempWriter.WrittenCount;");
                }
                else
                {
                    sb.AppendLine();
                }
                continue;
            }

            // write method
            var end = i + batch.Count;
            var dangerous = batch.UseDangerous ? "Dangerous" : "";
            sb.Append(indent);
            if (i == 0 && writeObjectHeader)
            {
                sb.Append($"{writer}.{dangerous}WriteUnmanagedWithObjectHeader(");
                sb.Append(members.Length);
                sb.Append(", ");
            }
            else
            {
                sb.Append($"{writer}.{dangerous}WriteUnmanaged(");
            }

            for (int index = i; index < end; index++)
            {
                if (index != i)
                {
                    sb.Append(", ");
                }
                sb.Append("value.@");
                sb.Append(members[index].Name);
            }
            sb.Append(");");

            sb.AppendLine();
            i = end - 1;
        }

        return sb.ToString();
    }

    internal static string EmitDeserializeMembersCore(
        MemberShape[] members,
        EquatableArray<ScalarBatch> batches,
        string indent,
        bool versioned,
        bool honorFormatterOverrides)
    {
        var sb = new StringBuilder();
        for (int i = 0; i < members.Length; i++)
        {
            var batch = versioned || honorFormatterOverrides ? default : batches[i];
            if (batch.Count == 0)
            {
                sb.Append(indent);
                sb.AppendLine(members[i].EmitReadToDeserialize(
                    i,
                    versioned,
                    honorFormatterOverrides));
                continue;
            }

            // write read method
            var end = i + batch.Count;
            var dangerous = batch.UseDangerous ? "Dangerous" : "";
            sb.Append(indent);
            sb.Append($"reader.{dangerous}ReadUnmanaged(");

            for (int index = i; index < end; index++)
            {
                if (index != i)
                {
                    sb.Append(", ");
                }
                sb.Append("out __");
                sb.Append(members[index].Name);
            }
            sb.AppendLine(");");

            i = end - 1;
        }

        return sb.ToString();
    }

    string EmitReadRefDeserializeMembers(
        MemberShape[] members,
        string indent,
        bool includeCountJumps,
        bool honorFormatterOverrides)
    {
        return members
            .Select((member, index) =>
                indent +
                member.EmitReadRefDeserialize(
                    member.Order,
                    plan.IsVersioned,
                    honorFormatterOverrides) +
                (includeCountJumps
                    ? $" if (count == {index + 1}) goto SKIP_READ;"
                    : ""))
            .NewLine();
    }

    string EmitConstructor(MemberShape[] members)
        => $"new {TypeName}({string.Join(", ", plan.ConstructorArgumentSlots.Select((slot, index) =>
            $"{(Shape.ConstructorParameters[index].PassByIn ? "in " : "")}__{members[slot].Name}"))})";

    static string EmitDeserializeConstruction(MemberShape[] members, string indent)
    {
        return string.Join("," + Environment.NewLine, members
            .Where(x => x is { IsSettable: true, ConstructorParameter: null, SuppressDefaultInitialization: false })
            .Select(x => $"{indent}@{x.Name} = __{x.Name}"));
    }

    string EmitDeserializeConstructionWithBranching(MemberShape[] members, string indent)
    {
        var initialized = members
            .Select((x, i) => (x, i))
            .Where(v => v.x.SuppressDefaultInitialization);

        var lines = plan.IsVersioned
            ? initialized.Select(v => $"{indent}if (deltas.Length > {v.i} && deltas[{v.i}] != 0) value.@{v.x.Name} = __{v.x.Name};")
            : initialized.Select(v => $"{indent}if ({v.i + 1} <= count) value.@{v.x.Name} = __{v.x.Name};");

        return lines.NewLine();
    }

    string EmitUnionTemplate(UnionShape union)
    {
        var shape = plan.Shape;
        var classOrInterfaceOrRecord = shape.IsRecord ? "record" : shape.TargetKind == TypeKind.Interface ? "interface" : "class";

        var contextFactoryInterface =
            $"global::SharpPack.ISharpPackFormatterFactory<{TypeName}>";
        var selfFactoryRoot = plan.Names.SelfFactoryRoot;
        var contextFactoryMethod = $$"""

    [global::SharpPack.CompilerServices.Preserve]
    static global::SharpPack.SharpPackFormatter<{{TypeName}}> global::SharpPack.ISharpPackFormatterFactory<{{TypeName}}>.CreateFormatter()
    {
{{EmitFactoryRootRead(selfFactoryRoot)}}
        return new {{shape.SimpleName}}Formatter();
    }
""";
        const string scopedRef = "scoped ref";
        var writerParameter = shape.WriterTypeParameter;

        var code = $$"""

partial {{classOrInterfaceOrRecord}} {{TypeName}} : {{contextFactoryInterface}}
{
    static partial void StaticConstructor();

{{EmitSelfFactoryRoots(selfFactoryRoot, includeContextFactory: false)}}
{{contextFactoryMethod}}

    [global::SharpPack.CompilerServices.Preserve]
    sealed class {{shape.SimpleName}}Formatter : global::SharpPack.SharpPackFormatter<{{TypeName}}>
    {
{{EmitUnionTypeToTagField(union.Cases)}}

        [global::SharpPack.CompilerServices.Preserve]
        public override void Serialize<{{writerParameter}}>(ref global::SharpPack.SharpPackWriter<{{writerParameter}}> writer, {{scopedRef}} {{TypeName}}? value)
        {
{{EmitCallbacks(shape, CallbackPhase.Serializing, "            ")}}
{{EmitUnionSerializeBody(union)}}
{{EmitCallbacks(shape, CallbackPhase.Serialized, "            ")}}
        }

        [global::SharpPack.CompilerServices.Preserve]
        public override void Deserialize(ref global::SharpPack.SharpPackReader reader, {{scopedRef}} {{TypeName}}? value)
        {
{{EmitCallbacks(shape, CallbackPhase.Deserializing, "            ")}}
{{EmitUnionDeserializeBody(union)}}
{{EmitCallbacks(shape, CallbackPhase.Deserialized, "            ")}}
        }
    }
}
""";

        return code;
    }

    string EmitUnionFormatterTemplate(UnionShape union, ExternalUnionFormatterShape formatter, bool includeRegistration)
    {
        var writerTypeParameter = Shape.WriterTypeParameter;
        var symbolFullQualified = union.TypeName;
        var constraints = EmitTypeParameterConstraints(formatter.TypeParameters);
        var declaration = $$"""
[global::SharpPack.CompilerServices.Preserve]
partial class {{TypeName}} :
    global::SharpPack.SharpPackFormatter<{{symbolFullQualified}}>,
    global::SharpPack.ISharpPackFormatterFactory<{{symbolFullQualified}}>
{{constraints}}
{
    static global::SharpPack.SharpPackFormatter<{{symbolFullQualified}}>
        global::SharpPack.ISharpPackFormatterFactory<{{symbolFullQualified}}>.CreateFormatter()
    {
        return new {{TypeName}}();
    }

{{EmitUnionTypeToTagField(union.Cases)}}

        [global::SharpPack.CompilerServices.Preserve]
        public override void Serialize<{{writerTypeParameter}}>(ref global::SharpPack.SharpPackWriter<{{writerTypeParameter}}> writer, scoped ref {{symbolFullQualified}}? value)
        {
{{EmitCallbacks(Shape, CallbackPhase.Serializing, "            ")}}
{{EmitUnionSerializeBody(union)}}
{{EmitCallbacks(Shape, CallbackPhase.Serialized, "            ")}}
        }

        [global::SharpPack.CompilerServices.Preserve]
        public override void Deserialize(ref global::SharpPack.SharpPackReader reader, scoped ref {{symbolFullQualified}}? value)
        {
{{EmitCallbacks(Shape, CallbackPhase.Deserializing, "            ")}}
{{EmitUnionDeserializeBody(union)}}
{{EmitCallbacks(Shape, CallbackPhase.Deserialized, "            ")}}
        }
}
""";
        return includeRegistration
            ? declaration + Environment.NewLine + Environment.NewLine + EmitUnionContextRegistration(union.TypeName, formatter, TypeName)
            : declaration;
    }

    static string EmitUnionContextRegistration(string targetType, ExternalUnionFormatterShape formatter, string formatterType)
    {
        var typeParameters = EmitTypeParameterList(formatter.TypeParameters);
        var constraints = EmitTypeParameterConstraints(formatter.TypeParameters);
        return $$"""
[global::SharpPack.CompilerServices.Preserve]
public static class {{formatter.Name}}SharpPackContextExtensions
{
    public static global::SharpPack.SharpPackSerializerContextBuilder
        Register{{formatter.Name}}{{typeParameters}}(
            this global::SharpPack.SharpPackSerializerContextBuilder builder)
{{constraints}}
    {
        global::System.ArgumentNullException.ThrowIfNull(builder);
        return builder.RegisterFactory<
            {{targetType}},
            {{formatterType}}>();
    }
}
""";
    }

    internal static string EmitPartialTypeDeclaration(PartialTypeShape type)
    {
        var kind = type.IsNativeUnion ? "union" : (type.Kind, type.IsRecord, type.IsValueType) switch
        {
            (TypeKind.Interface, _, _) => "interface",
            (_, true, true) => "record struct",
            (_, true, false) => "record",
            (_, false, true) => "struct",
            _ => "class",
        };
        return $"partial {kind} {type.Name}{EmitTypeParameterList(type.TypeParameters)}";
    }

    static string EmitTypeParameterList(EquatableArray<TypeParameterShape> typeParameters)
        => typeParameters.Length == 0 ? "" : $"<{string.Join(", ", typeParameters.Select(static parameter => parameter.Name))}>";

    internal static string EmitTypeParameterConstraints(EquatableArray<TypeParameterShape> typeParameters)
    {
        var clauses = new List<string>();
        foreach (var parameter in typeParameters)
        {
            var constraints = new List<string>();
            var primary = parameter.Primary switch
            {
                PrimaryTypeConstraint.Unmanaged => "unmanaged",
                PrimaryTypeConstraint.ValueType => "struct",
                PrimaryTypeConstraint.ReferenceType => "class",
                PrimaryTypeConstraint.NullableReferenceType => "class?",
                PrimaryTypeConstraint.NotNull => "notnull",
                _ => null,
            };
            if (primary is not null)
                constraints.Add(primary);

            constraints.AddRange(parameter.ConstraintTypes);

            if (parameter.HasConstructorConstraint)
            {
                constraints.Add("new()");
            }

            if (constraints.Count != 0)
            {
                clauses.Add(
                    $"        where {parameter.Name} : {string.Join(", ", constraints)}");
            }
        }

        return clauses.Count == 0
            ? ""
            : string.Join(Environment.NewLine, clauses);
    }

    static string EmitUnionTypeToTagField(EquatableArray<UnionCaseShape> cases)
    {
        var elements = cases.Select(x => $"            {{ typeof({x.TypeName}), {x.Tag} }},").NewLine();

        return $$"""
        static readonly global::System.Collections.Generic.Dictionary<global::System.Type, ushort> __typeToTag = new({{cases.Length}})
        {
{{elements}}
        };
""";
    }

    string EmitUnionSerializeBody(UnionShape union)
    {
        var symbolFullQualified = union.TypeName;

        var writeBody = union.Cases
            .Select(x =>
            {
                var method = x.UsePackablePath ? "WritePackable" : "WriteValue";
                return $"                    case {x.Tag}: writer.{method}(global::System.Runtime.CompilerServices.Unsafe.As<{symbolFullQualified}?, {x.TypeName}>(ref value)); break;";
            })
            .NewLine();

        return $$"""
            if (value == null)
            {
                writer.WriteNullUnionHeader();
{{EmitCallbacks(Shape, CallbackPhase.Serialized, "            ")}}
                return;
            }

            if (__typeToTag.TryGetValue(value.GetType(), out var tag))
            {
                writer.WriteUnionHeader(tag);

                switch (tag)
                {
{{writeBody}}
                    default:
                        break;
                }
            }
            else
            {
                global::SharpPack.SharpPackSerializationException.ThrowNotFoundInUnionType(value.GetType(), typeof({{symbolFullQualified}}));
            }
""";
    }

    string EmitUnionDeserializeBody(UnionShape union)
    {
        var symbolFullQualified = union.TypeName;

        var readBody = union.Cases.Select(x =>
        {
            var tagTypeFullQualified = x.TypeName;

            var method = x.UsePackablePath ? "ReadPackable" : "ReadValue";

            var castString = x.UsePackablePath && symbolFullQualified != tagTypeFullQualified
                ? $"({tagTypeFullQualified})"
                : "";

            return $$"""
                case {{x.Tag}}:
                    if (value is {{tagTypeFullQualified}})
                    {
                        reader.{{method}}(ref global::System.Runtime.CompilerServices.Unsafe.As<{{symbolFullQualified}}?, {{tagTypeFullQualified}}>(ref value));
                    }
                    else
                    {
                        value = {{castString}}reader.{{method}}<{{tagTypeFullQualified}}>();
                    }
                    break;
""";
        }).NewLine();


        return $$"""
            if (!reader.TryReadUnionHeader(out var tag))
            {
                value = default;
{{EmitCallbacks(Shape, CallbackPhase.Deserialized, "                ")}}
                return;
            }

            switch (tag)
            {
{{readBody}}
                default:
                    global::SharpPack.SharpPackSerializationException.ThrowInvalidTag(tag, typeof({{symbolFullQualified}}));
                    break;
            }
""";
    }

    string EmitGenericCollectionTemplate(CollectionShape collection, string? selfFactoryRoot)
    {
        var formatter = collection.Kind switch
        {
            CollectionKind.Collection => "GenericCollectionFormatter",
            CollectionKind.Set => "GenericSetFormatter",
            CollectionKind.Dictionary => "GenericDictionaryFormatter",
            _ => throw new InvalidOperationException(),
        };

        var typeArgs = string.Join(", ", collection.TypeArguments);
        var contextFormatterType = $"global::SharpPack.Formatters.{formatter}<{TypeName}, {typeArgs}>";
        var contextFactoryInterface =
            $"global::SharpPack.ISharpPackFormatterFactory<{TypeName}>";
        var contextFactoryMethod = $$"""

    [global::SharpPack.CompilerServices.Preserve]
    static global::SharpPack.SharpPackFormatter<{{TypeName}}> global::SharpPack.ISharpPackFormatterFactory<{{TypeName}}>.CreateFormatter()
    {
{{EmitFactoryRootRead(selfFactoryRoot)}}
        return new {{contextFormatterType}}();
    }
""";

        var code = $$"""
partial class {{TypeName}} : {{contextFactoryInterface}}
{
    static partial void StaticConstructor();

{{EmitSelfFactoryRoots(selfFactoryRoot, includeContextFactory: false)}}
{{contextFactoryMethod}}
}
""";

        return code;
    }
}

internal static class MemberCSharpEmitter
{
    internal static string EmitSerialize(this MemberShape member,
        string writer,
        bool honorFormatterOverrides = false)
    {
        var name = member.Name;
        if (honorFormatterOverrides &&
            member.Kind is not MemberKind.Blank and not MemberKind.CustomFormatter)
        {
            return $"{writer}.WriteValue(value.@{name});";
        }

        switch (member.Kind)
        {
            case MemberKind.SharpPackable:
                return $"{writer}.WritePackable(value.@{name});";
            case MemberKind.Unmanaged:
            case MemberKind.Enum:
                return $"{writer}.WriteUnmanaged(value.@{name});";
            case MemberKind.UnmanagedNullable:
                return $"{writer}.DangerousWriteUnmanaged(value.@{name});";
            case MemberKind.String:
                return $"{writer}.WriteString(value.@{name});";
            case MemberKind.UnmanagedArray:
                return $"{writer}.WriteUnmanagedArray(value.@{name});";
            case MemberKind.SharpPackableArray:
                return $"{writer}.WritePackableArray(value.@{name});";
            case MemberKind.SharpPackableList:
                return $"global::SharpPack.Formatters.ListFormatter.SerializePackable(ref {writer}, value.@{name});";
            case MemberKind.SharpPackableUnmanagedList:
                return $"global::SharpPack.Formatters.ListFormatter.SerializePackableUnmanaged(ref {writer}, value.@{name});";
            case MemberKind.Array:
                return $"{writer}.WriteArray(value.@{name});";
            case MemberKind.Blank:
                return "";
            case MemberKind.CustomFormatter:
                return $"{writer}.WriteValueWithFormatter(__{name}Formatter, value.@{name});";
            default:
                return $"{writer}.WriteValue(value.@{name});";
        }
    }

    internal static string EmitVarIntLength(this MemberShape member)
    {
        switch (member.Kind)
        {
            case MemberKind.Unmanaged:
            case MemberKind.Enum:
            case MemberKind.UnmanagedNullable:
                return $"writer.WriteVarInt(global::System.Runtime.CompilerServices.Unsafe.SizeOf<{member.TypeName}>());";
            case MemberKind.String:
                return $"writer.WriteVarInt(writer.GetStringWriteLength(value.@{member.Name}));";
            case MemberKind.UnmanagedArray:
                return $"writer.WriteVarInt(writer.GetUnmanageArrayWriteLength<{member.ElementTypeName}>(value.@{member.Name}));";
            case MemberKind.Blank:
                return $"writer.WriteVarInt(0);";
            default:
                throw new InvalidOperationException("This MemberKind is not supported, Kind:" + member.Kind);
        }
    }

    internal static string EmitReadToDeserialize(this MemberShape member,
        int i,
        bool requireDeltaCheck,
        bool honorFormatterOverrides = false)
    {
        var name = member.Name;
        var equalDefault = member.Kind == MemberKind.Blank
            ? "{ }"
            : $"{{ __{name} = default; }}";

        var pre = requireDeltaCheck
            ? $"if (deltas[{i}] == 0) {equalDefault} else "
            : "";

        if (honorFormatterOverrides &&
            member.Kind is not MemberKind.Blank and not MemberKind.CustomFormatter)
        {
            return $"{pre}__{name} = reader.ReadValue<{member.TypeName}>();";
        }

        switch (member.Kind)
        {
            case MemberKind.SharpPackable:
                return $"{pre}__{name} = reader.ReadPackable<{member.TypeName}>();";
            case MemberKind.Unmanaged:
            case MemberKind.Enum:
                return $"{pre}reader.ReadUnmanaged(out __{name});";
            case MemberKind.UnmanagedNullable:
                return $"{pre}reader.DangerousReadUnmanaged(out __{name});";
            case MemberKind.String:
                return $"{pre}__{name} = reader.ReadString();";
            case MemberKind.UnmanagedArray:
                return $"{pre}__{name} = reader.ReadUnmanagedArray<{member.ElementTypeName}>();";
            case MemberKind.SharpPackableArray:
                return $"{pre}__{name} = reader.ReadPackableArray<{member.ElementTypeName}>();";
            case MemberKind.SharpPackableList:
                return $"{pre}__{name} = global::SharpPack.Formatters.ListFormatter.DeserializePackable<{member.ElementTypeName}>(ref reader);";
            case MemberKind.SharpPackableUnmanagedList:
                return $"{pre}__{name} = global::SharpPack.Formatters.ListFormatter.DeserializePackableUnmanaged<{member.ElementTypeName}>(ref reader);";
            case MemberKind.Array:
                return $"{pre}__{name} = reader.ReadArray<{member.ElementTypeName}>();";
            case MemberKind.Blank:
                return $"{pre}reader.Advance(deltas[{i}]);";
            case MemberKind.CustomFormatter:
                return $"{pre}__{name} = reader.ReadValueWithFormatter<{member.CustomFormatter!.FormatterType}, {member.TypeName}>(__{name}Formatter);";
            default:
                return $"{pre}__{name} = reader.ReadValue<{member.TypeName}>();";
        }
    }

    internal static string EmitReadRefDeserialize(this MemberShape member,
        int i,
        bool requireDeltaCheck,
        bool honorFormatterOverrides = false)
    {
        var name = member.Name;
        var pre = requireDeltaCheck
            ? $"if (deltas[{i}] != 0) "
            : "";

        if (honorFormatterOverrides &&
            member.Kind is not MemberKind.Blank and not MemberKind.CustomFormatter)
        {
            return $"{pre}reader.ReadValue(ref __{name});";
        }

        switch (member.Kind)
        {
            case MemberKind.SharpPackable:
                return $"{pre}reader.ReadPackable(ref __{name});";
            case MemberKind.Unmanaged:
            case MemberKind.Enum:
                return $"{pre}reader.ReadUnmanaged(out __{name});";
            case MemberKind.UnmanagedNullable:
                return $"{pre}reader.DangerousReadUnmanaged(out __{name});";
            case MemberKind.String:
                return $"{pre}__{name} = reader.ReadString();";
            case MemberKind.UnmanagedArray:
                return $"{pre}reader.ReadUnmanagedArray(ref __{name});";
            case MemberKind.SharpPackableArray:
                return $"{pre}reader.ReadPackableArray(ref __{name});";
            case MemberKind.SharpPackableList:
                return $"{pre}global::SharpPack.Formatters.ListFormatter.DeserializePackable(ref reader, ref __{name});";
            case MemberKind.SharpPackableUnmanagedList:
                return $"{pre}global::SharpPack.Formatters.ListFormatter.DeserializePackableUnmanaged(ref reader, ref __{name});";
            case MemberKind.Array:
                return $"{pre}reader.ReadArray(ref __{name});";
            case MemberKind.Blank:
                return $"{pre}reader.Advance(deltas[{i}]);";
            case MemberKind.CustomFormatter:
                return $"{pre}reader.ReadValueWithFormatter(__{name}Formatter, ref __{name});";
            default:
                return $"{pre}reader.ReadValue(ref __{name});";
        }
    }
}

